409	    let onNewThread: () -> Void
410	
411	    @State private var searchText = ""
412	
413	    private var filteredThreads: [BrowserThread] {
414	        let trimmedSearch = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
415	        let sortedThreads = threads.sorted { lhs, rhs in
416	            lhs.updatedAt > rhs.updatedAt
417	        }
418	
419	        guard trimmedSearch.isEmpty == false else {
420	            return sortedThreads
421	        }
422	
423	        return sortedThreads.filter { thread in
424	            thread.matchesHistorySearch(trimmedSearch)
425	        }
426	    }
